result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/money-mask/src/mask.ts", "content": "/**
 * Pure, DOM-free currency input masking.
 *
 * The intended usage from a controlled React-style input:
 *
 *   onChange={(e) => {
 *     const { value, caret } = formatAsTyped(prevValue, e.target.value, e.target.selectionStart, { locale: 'en-US' });
 *     setValue(value);
 *     requestAnimationFrame(() => input.setSelectionRange(caret, caret));
 *   }}
 *
 * All functions are pure; no browser APIs are used. Separators are derived
 * from `Intl.NumberFormat` for the given locale (cached), so en-US uses
 * `,` for grouping / `.` for decimal and de-DE uses `.` / `,`.
 */

export interface MaskOptions {
  /** BCP-47 locale, e.g. 'en-US', 'de-DE'. */
  locale: string;
  /** ISO 4217 code (accepted for API completeness; masking itself is currency-agnostic). */
  currency?: string;
}

export interface MaskResult {
  /** Reformatted string to store as the input's value. */
  value: string;
  /** Caret offset into `value`, anchored to the digit the user just typed. */
  caret: number;
}

interface Separators {
  group: string;
  decimal: string;
}

const sepCache = new Map<string, Separators>();

function separatorsFor(locale: string): Separators {
  const cached = sepCache.get(locale);
  if (cached) return cached;
  let seps: Separators;
  try {
    const parts = new Intl.NumberFormat(locale).formatToParts(1234567.891);
    seps = {
      group: parts.find((p) => p.type === 'group')?.value ?? ',',
      decimal: parts.find((p) => p.type === 'decimal')?.value ?? '.',
    };
    if (seps.group === seps.decimal) seps = { group: ',', decimal: '.' };
  } catch {
    seps = { group: ',', decimal: '.' };
  }
  sepCache.set(locale, seps);
  return seps;
}

function isDigit(ch: string): boolean {
  return ch >= '0' && ch <= '9';
}

interface Sanitized {
  int: string; // integer digits, leading zeros collapsed
  frac: string; // at most two fraction digits
  hasDecimal: boolean;
}

/**
 * Strip everything except digits and the locale's decimal separator.
 * The grouping separator is always dropped (it is regenerated by the
 * formatter), extra decimal separators are dropped, and the fraction is
 * capped at two digits.
 */
function sanitize(input: string, decimal: string): Sanitized {
  let int = '';
  let frac = '';
  let hasDecimal = false;
  for (const ch of input) {
    if (isDigit(ch)) {
      if (hasDecimal) {
        if (frac.length < 2) frac += ch;
      } else {
        int += ch;
      }
    } else if (ch === decimal && !hasDecimal) {
      hasDecimal = true;
    }
    // grouping separator and any other character: dropped
  }
  int = int.replace(/^0+(?=\d)/, '');
  if (int === '') int = '0';
  return { int, frac, hasDecimal };
}

/** Insert the grouping separator every three digits, counting from the right. */
function groupDigits(int: string, group: string): string {
  let out = '';
  const len = int.length;
  for (let i = 0; i < len; i++) {
    out += int[i];
    const remaining = len - i - 1;
    if (remaining > 0 && remaining % 3 === 0) out += group;
  }
  return out;
}

/**
 * Reformat the raw post-keystroke input and recompute the caret so it stays
 * anchored to the digit the user just edited — measured in *digits*, not in
 * string offsets, so inserting/removing grouping separators never makes the
 * caret jump.
 *
 * @param prev       Previously formatted value (kept for API symmetry/fast paths).
 * @param inputValue Raw value from the input element after the keystroke/paste.
 * @param caretPos   Caret position within `inputValue`.
 * @param options    Locale (+ optional currency).
 */
export function formatAsTyped(
  prev: string,
  inputValue: string,
  caretPos: number,
  options: MaskOptions,
): MaskResult {
  void prev;
  const { group, decimal } = separatorsFor(options.locale);

  const s = sanitize(inputValue, decimal);
  const groupedInt = groupDigits(s.int, group);
  const value =
    groupedInt + (s.hasDecimal ? decimal + s.frac : '');

  // Count how many real digits precede the caret in the raw input, and note
  // whether the caret sits directly after a (consumed) decimal separator.
  const clampedCaret = Math.max(0, Math.min(caretPos, inputValue.length));
  let hasDecimalBefore = false;
  let digitsBefore = 0;
  for (let i = 0; i < clampedCaret; i++) {
    const ch = inputValue[i];
    if (isDigit(ch)) digitsBefore++;
    else if (ch === decimal) hasDecimalBefore = true;
  }
  const caretAfterSeparator =
    clampedCaret > 0 && inputValue[clampedCaret - 1] === decimal;

  let caret: number;
  if (clampedCaret === 0) {
    caret = 0;
  } else if (caretAfterSeparator && s.hasDecimal && !hasDecimalBefore) {
    // Keep the caret hugging a freshly typed decimal separator.
    caret = groupedInt.length + 1;
  } else {
    // Walk the formatted output to the digit with this ordinal.
    caret = value.length; // clamp when raw had dropped/overflow digits
    let seen = 0;
    for (let i = 0; i < value.length; i++) {
      if (isDigit(value[i])) {
        seen++;
        if (seen === digitsBefore) {
          caret = i + 1;
          break;
        }
      }
    }
  }

  return { value, caret };
}

/**
 * Convert a masked (or plain) numeric string into integer cents using the
 * locale's separators. Returns 0 for an empty string and NaN for strings that
 * still contain illegal characters. Non-negative amounts only.
 */
export function toCents(value: string, locale: string): number {
  const trimmed = value.trim();
  if (trimmed === '') return 0;
  const { group, decimal } = separatorsFor(locale);
  const normalized = trimmed.split(group).join('').split(decimal).join('.');
  if (!/^(\d+(\.\d*)?|\.\d+)$/.test(normalized)) return NaN;
  return Math.round(parseFloat(normalized) * 100);
}

/**
 * Format integer cents as a locale number string with exactly two fraction
 * digits, e.g. fromCents(123456, 'de-DE') -> '1.234,56'.
 */
export function fromCents(cents: number, locale: string): string {
  return new Intl.NumberFormat(locale, {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  }).format(cents / 100);
}
