result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/money-mask/tests/mask.test.ts", "content": "import { describe, expect, it } from 'vitest';
import { formatAsTyped, fromCents, toCents } from '../src/mask';

interface Row {
  only?: boolean;
  name: string;
  prev: string;
  input: string;
  caret: number;
  value: string;
  outCaret: number;
}

describe('formatAsTyped / en-US', () => {
  const rows: Row[] = [
    {
      name: 'typing a digit mid-string regroups and keeps caret on the typed digit',
      prev: '1,234.56',
      input: '12,534.56',
      caret: 4,
      value: '12,534.56',
      outCaret: 4,
    },
    {
      name: 'typing a digit that opens a new group shifts the caret past the separator',
      prev: '1,000',
      input: '10,000',
      caret: 2,
      value: '10,000',
      outCaret: 2,
    },
    {
      name: 'typing the fourth integer digit inserts a group separator before the caret',
      prev: '999',
      input: '9999',
      caret: 4,
      value: '9,999',
      outCaret: 5,
    },
    {
      name: 'backspacing away a group separator keeps caret anchored to the digit',
      prev: '1,234',
      input: '1234',
      caret: 1,
      value: '1,234',
      outCaret: 1,
    },
    {
      name: 'backspacing the last digit',
      prev: '1,234',
      input: '123',
      caret: 3,
      value: '123',
      outCaret: 3,
    },
    {
      name: 'deleting a digit mid-string keeps caret on the neighbouring digit',
      prev: '1,234',
      input: '134',
      caret: 2,
      value: '134',
      outCaret: 2,
    },
    {
      name: 'pasting garbage keeps only digits and regroups',
      prev: '',
      input: '$1,2a4bc6@78',
      caret: 12,
      value: '124,678',
      outCaret: 7,
    },
    {
      name: 'pasting garbage with too many fraction digits caps at two',
      prev: '',
      input: 'x3.14159z',
      caret: 9,
      value: '3.14',
      outCaret: 4,
    },
    {
      name: 'typing the decimal separator keeps caret hugging it',
      prev: '12',
      input: '12.',
      caret: 3,
      value: '12.',
      outCaret: 3,
    },
    {
      name: 'a leading decimal separator becomes "0."',
      prev: '',
      input: '.',
      caret: 1,
      value: '0.',
      outCaret: 2,
    },
    {
      name: 'a second decimal separator is ignored',
      prev: '1.23',
      input: '1.2.3',
      caret: 5,
      value: '1.23',
      outCaret: 4,
    },
    {
      name: 'a third fraction digit is dropped',
      prev: '12.34',
      input: '12.345',
      caret: 6,
      value: '12.34',
      outCaret: 5,
    },
    {
      name: 'repeated leading zeros collapse',
      prev: '0',
      input: '00',
      caret: 2,
      value: '0',
      outCaret: 1,
    },
  ];

  it.each(rows)('$name', ({ prev, input, caret, value, outCaret }) => {
    expect(formatAsTyped(prev, input, caret, { locale: 'en-US' })).toEqual({
      value,
      caret: outCaret,
    });
  });
});

describe('formatAsTyped / de-DE', () => {
  const rows: Row[] = [
    {
      name: 'typing a digit mid-string regroups and keeps caret on the typed digit',
      prev: '1.234,56',
      input: '1.2534,56',
      caret: 4,
      value: '12.534,56',
      outCaret: 4,
    },
