    },
    {
      name: 'a second decimal comma is ignored',
      prev: '1,5',
      input: '1,5,',
      caret: 4,
      value: '1,5',
      outCaret: 3,
    },
    {
      name: 'a third fraction digit is dropped',
      prev: '12,34',
      input: '12,345',
      caret: 6,
      value: '12,34',
      outCaret: 5,
    },
    {
      name: 'pasting garbage with currency symbols and letters keeps digits and commas',
      prev: '',
