      prev: '9999',
      input: '99999',
      caret: 5,
      value: '99.999',
      outCaret: 6,
    },
  ];

  it.each(rows)('$name', ({ prev, input, caret, value, outCaret }) => {
    expect(formatAsTyped(prev, input, caret, { locale: 'de-DE' })).toEqual({
      value,
      caret: outCaret,
    });
  });
});

describe('toCents', () => {
  it.each([
    ['1,234.56', 'en-US', 123456],
    ['124,678', 'en-US', 12467800],
    ['0.05', 'en-US', 5],
    ['12.', 'en-US', 1200],
    ['1.234,56', 'de-DE', 123456],
    ['99.999', 'de-DE', 9999900],
    ['0,05', 'de-DE', 5],
    ['', 'en-US', 0],
    ['', 'de-DE', 0],
    ['$1,2a4bc6@78', 'en-US', NaN],
    ['€ 1.234,56', 'de-DE', NaN],
  ])('toCents(%j, %s) -> %i', (value, locale, expected) => {
    expect(toCents(value, locale)).toBe(expected);
  });

  it('rounds half a cent up instead of truncating via float error', () => {
    expect(toCents('0.125', 'en-US')).toBe(13);
  });
});

describe('fromCents', () => {
  it.each([
    [123456, 'en-US', '1,234.56'],
    [5, 'en-US', '0.05'],
    [123456, 'de-DE', '1.234,56'],
    [5, 'de-DE', '0,05'],
    [0, 'de-DE', '0,00'],
  ])('fromCents(%i, %s) -> %j', (cents, locale, expected) => {
    expect(fromCents(cents, locale)).toBe(expected);
  });
});

describe('round trip', () => {
  it.each([
    ['1,234.56', 'en-US'],
    ['1.234,56', 'de-DE'],
  ])('%s survives toCents -> fromCents', (value, locale) => {
    expect(fromCents(toCents(value, locale), locale)).toBe(value);
  });
});
"})
